d: Long?, body: JsonObject): Long = error("Not used by this UI test") override suspend fun deleteFolder(id: Long) = error("Not used by this UI test") override suspend fun deleteItem(id: Long) = error("Not used by this UI test") } @After fun close() { scope.cancel() } private fun text(id: Int) = InstrumentationRegistry.getInstrumentation().targetContext.getString(id) private fun show(role: String, largeDark: Boolean = false) { ui.setContent { val density = LocalDensity.current CompositionLocalProvider(LocalDensity provides Density(density.density, if (largeDark) 1.8f else density.fontScale), LocalUriHandler provides object : UriHandler { override fun openUri(uri: String) { openedUrls.add(uri) } }) { MaterialTheme(colorScheme = if (largeDark) darkColorScheme() else lightColorScheme()) { NotesContent(controller) } } } ui.runOnIdle { controller.sessionChanged(role, true) } ready() } private fun ready() = ui.waitUntil(5000) { controller.state.value.fresh && !controller.state.value.refreshing && !controller.state.value.saving } private fun click(id: Int) = ui.onAllNodesWithText(text(id)).onLast().performScrollTo().performClick() private fun screenshot(name: String) { ui.waitForIdle() val instrumentation = InstrumentationRegistry.getInstrumentation() val folder = File(instrumentation.targetContext.getExternalFilesDir(null), "notes-qa").apply { mkdirs() } val bitmap = instrumentation.uiAutomation.takeScreenshot() File(folder, "$name.png").outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG, 100, it) } bitmap.recycle() } @Test fun folderNavigatorHasNoItemsAndNestedReaderSelectionIsDirectOnly() { show("Reader") ui.onNodeWithTag("notes_folder_13").assertExists() ui.onNodeWithText("Diary item").assertDoesNotExist() ui.onNodeWithText("Task item").assertDoesNotExist() screenshot("01-folders-only") ui.onNodeWithTag("notes_folder_13").performScrollTo().performClick() ui.onNodeWithTag("notes_item_43").assertExists() ui.onNodeWithTag("notes_item_42").assertDoesNotExist() u